from netmiko import ConnectHandler

routers = {
    "HQ": "192.168.122.6",
    "Branch1": "192.168.122.5",
    "Branch2": "192.168.122.7",
}

def go(name, ip, cmds):
    print(f"\n{'='*25} {name} {'='*25}")
    dev = ConnectHandler(device_type="vyos", host=ip, username="vyos", password="test")
    for c in cmds:
        print(f"\n--- {c} ---")
        print(dev.send_command(c, read_timeout=60))
    dev.disconnect()

base = [
    "show interfaces",
    "show ip ospf neighbor",
    "show ip route",
    "show configuration commands | grep ospf",
]

for n, ip in routers.items():
    go(n, ip, base)

print("\n\n===== PING TESTS =====")
pings = {
    "HQ": [
        "ping 10.10.5.254 source-address 10.10.0.1 count 3",
